/* ===== Mountain / יקב טורא — warehouse app v2 ===== */
/* UTF-8 fix for qrcode-generator (default is ISO-8859-1 and mangles Hebrew) */
if(typeof qrcode!=='undefined'&&qrcode.stringToBytes){
  qrcode.stringToBytes=function(str){
    const out=[];
    for(let i=0;i<str.length;i++){
      let c=str.charCodeAt(i);
      if(c<0x80)out.push(c);
      else if(c<0x800){out.push(0xC0|(c>>6),0x80|(c&0x3F));}
      else if(c<0xD800||c>=0xE000){out.push(0xE0|(c>>12),0x80|((c>>6)&0x3F),0x80|(c&0x3F));}
      else{i++;c=0x10000+(((c&0x3FF)<<10)|(str.charCodeAt(i)&0x3FF));
        out.push(0xF0|(c>>18),0x80|((c>>12)&0x3F),0x80|((c>>6)&0x3F),0x80|(c&0x3F));}
    }
    return out;
  };
}
